export function getShuffledQuestions(count = 21): Question[] {
  return [...QUESTIONS]
    .sort(() => Math.random() - 0.5)
    .slice(0, count)
    .map(q => {
      if (Math.random() > 0.5) {
        return { ...q, optionA: q.optionB, optionB: q.optionA, correctAnswer: q.correctAnswer === 'A' ? 'B' : 'A' }
      }
      return q
    })
}
